  if (idx == 0) return texture(uTex0, uv);
  if (idx == 1) return texture(uTex1, uv);
  if (idx == 2) return texture(uTex2, uv);
  if (idx == 3) return texture(uTex3, uv);
  if (idx == 4) return texture(uTex4, uv);
  return texture(uTex5, uv);
